DROP TABLE IF EXISTS PBC_SPE_COUNTER_PARTY;
CREATE TABLE `pbc_spe_counter_party` (
  `PBC_UUID` varchar(64) NOT NULL COMMENT 'UUID',
  `PARTY_ORG_CODE` varchar(200) DEFAULT NULL COMMENT '交易对手机构编码',
  `PARTY_ORG_NAME` varchar(120) DEFAULT NULL COMMENT '交易对手机构名称',
  `PARTY_PROD_ID` varchar(15) DEFAULT NULL COMMENT '交易对手产品代码',
  `PARTY_PROD_NAME` varchar(120) DEFAULT NULL COMMENT '交易对手产品名称',
  `PARTY_PROD_TYPE` varchar(1) DEFAULT NULL COMMENT '交易对手产品种类',
  `ASSET_CODE` varchar(50) NOT NULL COMMENT '资产代码',
  `ASSET_TYPE` varchar(5) DEFAULT NULL COMMENT '资产负债项目',
  `STATUS` varchar(2) DEFAULT NULL COMMENT '数据状态: A：待处理 D：删除 E：有效 M：修改',
  `CREATE_USER` varchar(20) DEFAULT NULL COMMENT '创建人',
  `CREATE_DEPT` varchar(20) DEFAULT NULL COMMENT '创建部门',
  `CREATE_TIME` timestamp(6) NULL DEFAULT NULL COMMENT '创建时间',
  `UPDATE_USER` varchar(20) DEFAULT NULL COMMENT '更新人',
  `UPDATE_TIME` timestamp(6) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`PBC_UUID`)
)COMMENT='特定目的载体对手方信息维护表';


